def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv"
    # Try common encodings for Windows-exported CSVs
    try:
        return pd.read_csv(path, encoding="cp1252")
    except UnicodeDecodeError:
        return pd.read_csv(path, encoding="latin1")

def process(cleanReportCategories2024) -> pd.DataFrame:
    import pandas as pd

    df = cleanReportCategories2024.copy()

    # Find first position where cumulative share reaches at least 50%
    reached = df[df["cumShare"] >= 0.5].head(1)
    if reached.empty:
        k = pd.NA
    else:
        k = int(reached.index[0]) + 1  # index is 0-based rank in sorted-by-reports table

    return pd.DataFrame([{"minNumCategories": k}])
